"use strict";function deleteTeam(n){confirm("Are you sure you want to delete this team?",function(){$.post(_global.root+"team/Delete",{id:n},function(t){t.IsSuccessful?($("#row"+n).remove(),autoIndex()):alert(t.Message)})})}function initCreateEditPage(){var n=$("#successed").val();n==="true"&&confirm('<i class="icon-success mdi mdi-checkbox-marked-circle-outline"><\/i><p>Successfull!<\/p><p>Press OK to continue<\/p>',function(){document.location=_global.root+"Team/Index"})}$(document).ready(function(){$(".form-create-edit").length>0&&initCreateEditPage();floatThead("table#data")});